python3 - <<'EOF'
p = "src/server/services/invitation-service.ts"
s = open(p).read()

start = s.index("/**\n * Bulk invite.")
new_tail = '''/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite. The same
 * holds for duplicates: a batch naming an address twice, or an address that
 * is already a member or already has a pending invitation, creates nothing.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  return issueInvitations(actor, input, null);
}

/**
 * Shared by invite and re-send. `replacing` is the invitation a re-send
 * withdraws: it is only revoked once the new one is known to be issuable, and
 * the seat it may still hold is not counted against its own replacement.
 */
async function issueInvitations(
  actor: Actor,
  input: InviteMembersInput,
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  if (org.archivedAt !== null) {
    throw new Error("That organization has been deleted");
  }

  await assertInvitable(input.orgId, input.invites, replacing);

  const pending = (
    await invitationRepo.listPendingInvitations(input.orgId)
  ).filter((row) => row.id !== replacing?.id);

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) + pending.length;

  if (
    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
  ) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  if (replacing !== null) {
    await invitationRepo.revokeInvitation(input.orgId, replacing.id);
  }

  const invitations: Invitation[] = [];

  for (const invite of input.invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/** Addresses are compared without regard to letter case. */
function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * Refuses the whole batch when it names an address twice, or an address that
 * already belongs to a current member or already has a pending invitation.
 */
async function assertInvitable(
  orgId: OrgId,
  invites: InviteMembersInput["invites"],
  replacing: Invitation | null,
): Promise<void> {
