 * A session never defaults to an org its user no longer belongs to, or one
 * that has been deleted: such a stale default resolves as "no active org".
 */
export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  const principal = await sessionRepo.findSessionByTokenHash(hashToken(token));
  if (principal === null || principal.activeOrgId === null) return principal;

  const member = await memberRepo.findMember(
    principal.activeOrgId,
    principal.userId,
  );
  const org = member ? await orgRepo.findOrgById(principal.activeOrgId) : null;
  if (org !== null && org.archivedAt === null) return principal;

  return { ...principal, activeOrgId: null };
}'''
