import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("$P/tests/server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("$P/tests/server/_support/doubles/misc")).rateLimitModule);

import { hashToken } from "@/lib/hash";
import { getDb, sessions, notifications } from "@/server/db";
import { eq } from "drizzle-orm";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import * as digestService from "@/server/services/digest-service";
import { notify } from "@/server/services/notification-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});
afterAll(() => cleanup());

const DAY = 24 * 60 * 60 * 1000;

describe("flows", () => {
  it("expiry is 14 days; next morning still valid", async () => {
    const t = await createTenant("exp", "growth");
    const inv = await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "x@exp.test", role: "member" });
    const diff = Date.parse(inv.expiresAt) - Date.parse(inv.createdAt);
    expect(Math.round(diff / DAY)).toBe(14);
  });

  it("seats: revoked and expired free their seat; page lists only pending", async () => {
    const t = await createTenant("seats", "free");
    // remove two so there are 2 members on a 3 seat plan
    const m = await memberRepo.findMember(t.org.id, t.userIds.member);
    const v = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m!.id });
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: v!.id });
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(2);
    const a = await invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "a@seats.test", role: "member" });
    await invitationService.revokeInvitation(t.actors.owner, a.id);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "old@seats.test", role: "member", expiresInDays: -3 }, t.userIds.owner, hashToken("z".repeat(32)));
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(0);
    expect(await invitationRepo.listPendingInvitations(t.org.id)).toHaveLength(0);
    const b = await invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "b@seats.test", role: "member" });
    expect(b.email).toBe("b@seats.test");
    await expect(invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "c@seats.test", role: "member" })).rejects.toThrow(/seats/);
    // former member can be re-invited? seats full now; revoke b
    await invitationService.revokeInvitation(t.actors.owner, b.id);
    await invitationService.inviteMember(t.actors.owner, { orgId: t.org.id, email: "MEMBER@seats.test", role: "member" });
  });

  it("duplicates refused", async () => {
    const t = await createTenant("dups", "growth");
    await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "p@dups.test", role: "member" });
    await expect(invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "P@Dups.test", role: "member" })).rejects.toThrow(/pending/);
    await expect(invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "Viewer@dups.test", role: "member" })).rejects.toThrow(/member/);
    await expect(invitationService.inviteMembers(t.actors.admin, { orgId: t.org.id, invites: [{ email: "q@dups.test", role: "member" }, { email: "Q@dups.test", role: "viewer" }] })).rejects.toThrow();
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(1);
  });

  it("accept: email match, deleted org, used up, full member", async () => {
    const t = await createTenant("acc", "growth");
    const tok = "k".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "Joiner@acc.test", role: "admin", expiresInDays: 14 }, t.userIds.admin, hashToken(tok));
    const other = await userRepo.insertUser({ email: "other@acc.test", name: "o", passwordHash: "x" });
    await expect(invitationService.acceptInvitation(other.id, { token: tok })).rejects.toThrow(/different/);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(1);
    const joiner = await userRepo.insertUser({ email: "joiner@acc.test", name: "j", passwordHash: "x" });
    const member = await invitationService.acceptInvitation(joiner.id, { token: tok });
