import { getDb, sessions } from "@/server/db";
import { eq } from "drizzle-orm";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => { vi.useRealTimers(); cleanup(); });
const DAY = 86400000;

describe("timed", () => {
  it("next morning accept works; expiry frees seat; resend after expiry; old link dead", async () => {
    const t = await createTenant("timed", "free");
    vi.useFakeTimers();
    const start = new Date("2026-10-01T09:00:00Z");
    vi.setSystemTime(start);
    // free plan 3 seats, tenant has 4 members -> can't invite. Use growth-like: make new tenant
    const g = await createTenant("timedg", "growth");
    const inv = await invitationService.inviteMember(g.actors.admin, { orgId: g.org.id, email: "morning@timedg.test", role: "viewer" });
    const token1 = (globalThis as any).lastToken as string;
    vi.setSystemTime(new Date(start.getTime() + 0.9 * DAY));
    const u = await userRepo.insertUser({ email: "morning@timedg.test", name: "m", passwordHash: "x" });
    const m = await invitationService.acceptInvitation(u.id, { token: token1 });
    expect(m.role).toBe("viewer");

    const inv2 = await invitationService.inviteMember(g.actors.admin, { orgId: g.org.id, email: "slow@timedg.test", role: "admin" });
    const token2 = (globalThis as any).lastToken as string;
    expect(await invitationRepo.countPendingInvitations(g.org.id)).toBe(1);
    vi.setSystemTime(new Date(start.getTime() + 16 * DAY));
    expect(await invitationRepo.countPendingInvitations(g.org.id)).toBe(0);
    const slow = await userRepo.insertUser({ email: "slow@timedg.test", name: "s", passwordHash: "x" });
    await expect(invitationService.acceptInvitation(slow.id, { token: token2 })).rejects.toThrow(/expired/);
    const re = await invitationService.resendInvitation(g.actors.admin, inv2.id);
    const token3 = (globalThis as any).lastToken as string;
    expect(re.role).toBe("admin");
    expect(Date.parse(re.expiresAt)).toBe(start.getTime() + 16 * DAY + 14 * DAY);
    await expect(invitationService.acceptInvitation(slow.id, { token: token2 })).rejects.toThrow(/revoked/);
    const sm = await invitationService.acceptInvitation(slow.id, { token: token3 });
    expect(sm.role).toBe("admin");
    void inv; void t;
    vi.useRealTimers();
  });

  it("deleting org clears every session defaulting to it", async () => {
    const t = await createTenant("delorg", "growth");
    const o = await createTenant("delorg-other", "growth");
    await sessionService.createSessionToken(t.userIds.admin);
    const { token } = await sessionService.createSessionToken(t.userIds.member);
    await sessionService.createSessionToken(o.userIds.member);
    const rows = getDb().select().from(sessions).all();
    for (const r of rows) {
      await sessionRepo.setActiveOrg(r.id as never, r.userId === o.userIds.member ? o.org.id : t.org.id);
    }
    expect((await sessionService.resolveSession(token))?.activeOrgId).toBe(t.org.id);
    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    const after = getDb().select().from(sessions).all();
    expect(after.filter((r) => r.activeOrgId === t.org.id)).toHaveLength(0);
    expect(after.filter((r) => r.activeOrgId === o.org.id)).toHaveLength(1);
    expect((await sessionService.resolveSession(token))?.activeOrgId).toBeNull();
    void eq;
  });
});
